import math
        import random
        import time

        LANGUAGE_WRAPPER = 'Let A = (0, 0). Fix coprime integers {p} and {q} with p^2 + q^2 > 0, and let u be the unit vector u = (p/√(p^2+q^2), q/√(p^2+q^2)). Consider a convex equilateral hexagon ABCDEF with ∠FAB = 120°, and with opposite sides parallel in the pattern AB ∥ DE, BC ∥ EF, CD ∥ FA. Assume that the six scalar projections of the vertices A, B, C, D, E, F onto the line in direction u are the six distinct elements of the set {0, {proj_step}, 2·{proj_step}, 3·{proj_step}, 4·{proj_step}, 5·{proj_step}} (in some order). The area of the hexagon can be written in the form m√n with n squarefree. Find m + n.'

        class _RNGShim:
    def __init__(self, seed: int):
        import random as _random
        self._seed = int(seed)
        self._r = _random.Random(self._seed)

    def random(self): return self._r.random()
    def uniform(self, a, b): return self._r.uniform(a, b)
    def randint(self, a, b): return self._r.randint(a, b)
    def randrange(self, *args): return self._r.randrange(*args)
    def choice(self, seq): return self._r.choice(seq)
    def choices(self, population, weights=None, cum_weights=None, k: int = 1):
        return self._r.choices(population, weights=weights, cum_weights=cum_weights, k=k)
    def sample(self, population, k: int): return self._r.sample(population, k)
    def shuffle(self, x):
        self._r.shuffle(x)
        return x
    def getrandbits(self, k: int): return self._r.getrandbits(k)

        import math

def generator(rng):
    # Choose a non-axis, nontrivial direction (p,q) with gcd=1
    # Avoid (0,1), (1,0), and very small magnitudes to discourage trivialities
    while True:
        p = rng.randint(-5, 5)
        q = rng.randint(-5, 5)
        if p == 0 and q == 0:
            continue
        if abs(p) == 1 and q == 0:
            continue
        if abs(q) == 1 and p == 0:
            continue
        g = math.gcd(abs(p), abs(q))
        if g != 1:
            continue
        # avoid directions too close to axes to keep it nontrivial
        if abs(p) <= 1 and abs(q) <= 1:
            continue
        break
    # Choose a projection step (integer) reasonably sized
    proj_step = rng.randint(2, 12)
    return {"p": p, "q": q, "proj_step": proj_step}

