    proj_step = assign["proj_step"]
    # Basic domain checks
    if not (isinstance(p, int) and isinstance(q, int) and isinstance(proj_step, int)):
        # Types must be ints
        return (False, None)
    if p == 0 and q == 0:
        # Direction vector cannot be zero
        return (False, None)
    if proj_step <= 0:
        # Step must be positive
        return (False, None)
    if math.gcd(abs(p), abs(q)) != 1:
        # Enforce primitive direction for stated unit vector description
        return (False, None)
    # The area for this family is invariant under choice of direction and equals 12 * proj_step^2 * sqrt(3)
    # so m = 12 * proj_step^2, n = 3 (squarefree)
    m = 12 * (proj_step ** 2)
    n = 3
    answer = m + n
    return (True, answer)


        def generate_valid_instance(seed: int, timeout_seconds: float = 10.0):
            """Return dict with assignment/question/answer or raise RuntimeError."""
            start = time.time()
            attempts = 0
            while time.time() - start < timeout_seconds:
                attempts += 1
                rng = _RNGShim(seed + attempts)
